// Bildirimler Task 3: "bildirim-gonder" Edge Function (Deno).
//
// DEPLOY NOTU: `verify_jwt` KAPALI olmali. Cagriyi pg_net yapiyor ve
// elinde bir kullanici JWT'si yok; yetkilendirme tamamen asagidaki sir
// dogrulamasina dayaniyor. Tam yorumlu kaynak depoda:
// mobil/supabase/functions/bildirim-gonder/index.ts

import { createClient, type SupabaseClient } from 'npm:@supabase/supabase-js@2'
import {
  bildirimGovdesi,
  govdeyiCozumle,
  hedefleriBelirle,
  ozBildirimMi,
  VARSAYILAN_AD,
  type Olay,
} from './saf.ts'

const EXPO_PUSH_URL = 'https://exp.host/--/api/v2/push/send'
const EXPO_PARTI_BOYU = 100

let sirOnbellek: string | null = null
let sonSirOkumasi = 0
const SIR_TAZELEME_ARALIGI_MS = 60_000

async function siriOku(yonetici: SupabaseClient, tazele: boolean): Promise<string | null> {
  if (sirOnbellek !== null && !tazele) return sirOnbellek

  const simdi = Date.now()
  if (sonSirOkumasi !== 0 && simdi - sonSirOkumasi < SIR_TAZELEME_ARALIGI_MS) return sirOnbellek

  const { data, error } = await yonetici.rpc('bildirim_siri_oku')
  sonSirOkumasi = simdi

  if (error) {
    console.error('bildirim-gonder: sir okunamadi', { kod: error.code })
    return sirOnbellek
  }

  if (typeof data === 'string' && data.length > 0) {
    sirOnbellek = data
  } else {
    console.error('bildirim-gonder: sir bos donduruldu')
  }
  return sirOnbellek
}

function esitSir(a: string, b: string): boolean {
  if (a.length !== b.length) return false
  let fark = 0
  for (let i = 0; i < a.length; i++) fark |= a.charCodeAt(i) ^ b.charCodeAt(i)
  return fark === 0
}

/**
 * Olayin gercekten olup olmadigini veritabanina sorar.
 */
async function kaynakDogrula(yonetici: SupabaseClient, olay: Olay): Promise<boolean> {
  try {
    if (olay.olay === 'mesaj') {
      const { data, error } = await yonetici
        .from('mesajlar')
        .select('id')
        .eq('id', olay.mesaj_id)
        .eq('konusma_id', olay.konusma_id)
        .eq('gonderen_id', olay.gonderen_id)
        .limit(1)
      if (error) throw error
      return (data ?? []).length > 0
    }

    if (olay.olay === 'takip_istegi' || olay.olay === 'takip_kabul' || olay.olay === 'takip_eklendi') {
      // takip_eklendi de 'kabul' satiriyla dogrulanir: dogrudan ekleme
      // satiri baslangictan 'kabul' yazar.
      const { data, error } = await yonetici
        .from('takipler')
        .select('durum')
        .eq('takip_eden_id', olay.takip_eden_id)
        .eq('takip_edilen_id', olay.takip_edilen_id)
        .eq('durum', olay.olay === 'takip_istegi' ? 'beklemede' : 'kabul')
        .limit(1)
      if (error) throw error
      return (data ?? []).length > 0
    }

    if (olay.olay === 'etiket_istegi' || olay.olay === 'etiket_eklendi') {
      // IKI SEY birden dogrulaniyor: etiket satiri gercekten var mi ve
      // check-in'in sahibi govdede yazan etiketleyen mi.
      const { data: etiket, error: etiketHatasi } = await yonetici
        .from('check_in_etiketleri')
        .select('durum')
        .eq('check_in_id', olay.check_in_id)
        .eq('kullanici_id', olay.etiketlenen_id)
        .eq('durum', olay.olay === 'etiket_istegi' ? 'bekliyor' : 'onaylandi')
        .limit(1)
      if (etiketHatasi) throw etiketHatasi
      if ((etiket ?? []).length === 0) return false

      const { data: checkIn, error: checkInHatasi } = await yonetici
        .from('check_inler')
        .select('id')
        .eq('id', olay.check_in_id)
        .eq('kullanici_id', olay.etiketleyen_id)
        .limit(1)
      if (checkInHatasi) throw checkInHatasi
      return (checkIn ?? []).length > 0
    }

    // sohbet_istegi / sohbet_kabul. Tablodaki sutun adi `alan_id`,
    // sozlesmedeki alan adi `hedef_id`.
    const { data, error } = await yonetici
      .from('sohbet_istekleri')
      .select('durum')
      .eq('gonderen_id', olay.gonderen_id)
      .eq('alan_id', olay.hedef_id)
      .eq('durum', olay.olay === 'sohbet_istegi' ? 'beklemede' : 'kabul')
      .limit(1)
    if (error) throw error
    return (data ?? []).length > 0
  } catch (e) {
    const kod = (e as { code?: string })?.code
    console.error('bildirim-gonder: kaynak satiri okunamadi', { olay: olay.olay, kod })
    return false
  }
}

async function konusmaDigerUyeleri(
  yonetici: SupabaseClient,
  konusmaId: string,
  gonderenId: string
): Promise<string[]> {
  const { data, error } = await yonetici
    .from('konusma_uyeleri')
    .select('kullanici_id')
    .eq('konusma_id', konusmaId)
    .neq('kullanici_id', gonderenId)

  if (error) {
    console.error('bildirim-gonder: konusma uyeleri okunamadi', { kod: error.code })
    return []
  }
  return (data ?? []).map((s: { kullanici_id: string }) => s.kullanici_id)
}

/** Karsi tarafin gorunen adi; profil yoksa notr karsilik. */
async function adiOku(yonetici: SupabaseClient, kullaniciId: string): Promise<string> {
  const { data, error } = await yonetici
    .from('profiller')
    .select('ad')
    .eq('id', kullaniciId)
    .maybeSingle()

  if (error) {
    console.error('bildirim-gonder: ad okunamadi', { kod: error.code })
    return VARSAYILAN_AD
  }
  const ad = data?.ad as string | undefined
  return ad && ad.trim().length > 0 ? ad : VARSAYILAN_AD
}

async function jetonlariOku(yonetici: SupabaseClient, aliciId: string): Promise<string[]> {
  const { data, error } = await yonetici
    .from('bildirim_jetonlari')
    .select('jeton')
    .eq('kullanici_id', aliciId)

  if (error) {
    console.error('bildirim-gonder: jetonlar okunamadi', { kod: error.code })
    return []
  }
  return (data ?? []).map((s: { jeton: string }) => s.jeton)
}

async function olecekJetonlariSil(
  yonetici: SupabaseClient,
  aliciId: string,
  jetonlar: string[]
): Promise<void> {
  if (jetonlar.length === 0) return
  const { error } = await yonetici
    .from('bildirim_jetonlari')
    .delete()
    .eq('kullanici_id', aliciId)
    .in('jeton', jetonlar)
  if (error) {
    console.error('bildirim-gonder: olu jeton silinemedi', { kod: error.code })
  }
}

type ExpoSonuc = { status?: string; details?: { error?: string } }

function parcala<T>(dizi: T[], boy: number): T[][] {
  const parcalar: T[][] = []
  for (let i = 0; i < dizi.length; i += boy) parcalar.push(dizi.slice(i, i + boy))
  return parcalar
}

async function expoyaGonder(
  jetonlar: string[],
  govde: string,
  data: Record<string, string>
): Promise<{ hata: boolean; olu: string[] }> {
  const olu: string[] = []
  let hata = false

  for (const parca of parcala(jetonlar, EXPO_PARTI_BOYU)) {
    const mesajlar = parca.map((jeton) => ({ to: jeton, body: govde, data, sound: 'default' }))

    let yanit: Response
    try {
      yanit = await fetch(EXPO_PUSH_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
        body: JSON.stringify(mesajlar),
      })
    } catch {
      console.error('bildirim-gonder: Expo cagrisi yapilamadi')
      hata = true
      continue
    }

    if (!yanit.ok) {
      console.error('bildirim-gonder: Expo hata durumu', { durum: yanit.status })
      hata = true
      continue
    }

    let govdeJson: { data?: ExpoSonuc[] }
    try {
      govdeJson = await yanit.json()
    } catch {
      console.error('bildirim-gonder: Expo yaniti cozulemedi')
      hata = true
      continue
    }

    const sonuclar = govdeJson.data ?? []
    if (sonuclar.length !== parca.length) {
      console.error('bildirim-gonder: Expo sonuc sayisi eslesmiyor', {
        beklenen: parca.length,
        gelen: sonuclar.length,
      })
      hata = true
      continue
    }

    sonuclar.forEach((sonuc, i) => {
      if (sonuc?.status === 'error') {
        if (sonuc.details?.error === 'DeviceNotRegistered') olu.push(parca[i])
        else hata = true
      }
    })
  }

  return { hata, olu }
}

function yanit(durum: number, govde: Record<string, unknown>): Response {
  return new Response(JSON.stringify(govde), {
    status: durum,
    headers: { 'Content-Type': 'application/json' },
  })
}

Deno.serve(async (req: Request): Promise<Response> => {
  if (req.method !== 'POST') return yanit(405, { hata: 'yalnizca POST' })

  const supabaseUrl = Deno.env.get('SUPABASE_URL')
  const servisAnahtari = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')
  if (!supabaseUrl || !servisAnahtari) {
    console.error('bildirim-gonder: ortam degiskenleri eksik')
    return yanit(500, { hata: 'yapilandirma eksik' })
  }

  const yonetici = createClient(supabaseUrl, servisAnahtari, {
    auth: { persistSession: false, autoRefreshToken: false },
  })

  // 1) Sir. Dogrulanmadan HICBIR sey yapilmiyor.
  const gelenSir = req.headers.get('X-Bildirim-Sir')
  if (!gelenSir) return yanit(401, { hata: 'yetkisiz' })

  let sir = await siriOku(yonetici, false)
  if (sir === null) {
    return yanit(500, { hata: 'sir okunamadi' })
  }
  if (!esitSir(gelenSir, sir)) {
    sir = await siriOku(yonetici, true)
    if (sir === null || !esitSir(gelenSir, sir)) {
      console.warn('bildirim-gonder: sir eslesmedi')
      return yanit(401, { hata: 'yetkisiz' })
    }
  }

  // 2) Govde BICIMI.
  let ham: unknown
  try {
    ham = await req.json()
  } catch {
    return yanit(400, { hata: 'govde cozulemedi' })
  }

  const olay = govdeyiCozumle(ham)
  if (!olay) return yanit(400, { hata: 'gecersiz olay' })

  // 3) Olay GERCEKTEN oldu mu.
  if (!(await kaynakDogrula(yonetici, olay))) {
    console.warn('bildirim-gonder: olay dogrulanamadi', { olay: olay.olay })
    return yanit(200, { gonderildi: 0, neden: 'olay dogrulanamadi' })
  }

  // 4) Alicilar.
  const digerUyeler =
    olay.olay === 'mesaj'
      ? await konusmaDigerUyeleri(yonetici, olay.konusma_id, olay.gonderen_id)
      : []

  const hedefler = hedefleriBelirle(olay, digerUyeler)
  if (hedefler.length === 0) {
    console.log('bildirim-gonder: alici bulunamadi', { olay: olay.olay })
    return yanit(200, { gonderildi: 0, neden: 'alici yok' })
  }

  const gonderilecekler = hedefler.filter((h) => !ozBildirimMi(h.aliciId, olay.aktor_id))
  if (gonderilecekler.length === 0) {
    console.log('bildirim-gonder: oz-bildirim atlandi', { olay: olay.olay })
    return yanit(200, { gonderildi: 0, neden: 'oz-bildirim' })
  }

  // 5) Metin.
  const ad = await adiOku(yonetici, gonderilecekler[0].karsiTarafId)
  const govde = bildirimGovdesi(olay.olay, ad)

  let toplamJeton = 0
  let toplamOlu = 0
  let hataVar = false

  for (const hedef of gonderilecekler) {
    const jetonlar = await jetonlariOku(yonetici, hedef.aliciId)
    if (jetonlar.length === 0) {
      console.log('bildirim-gonder: jeton yok', { olay: olay.olay, alici: hedef.aliciId })
      continue
    }

    const { hata, olu } = await expoyaGonder(jetonlar, govde, {
      tur: olay.olay,
      kullaniciId: hedef.karsiTarafId,
    })
    await olecekJetonlariSil(yonetici, hedef.aliciId, olu)

    toplamJeton += jetonlar.length
    toplamOlu += olu.length
    hataVar = hataVar || hata

    console.log('bildirim-gonder: alici islendi', {
      olay: olay.olay,
      alici: hedef.aliciId,
      jeton: jetonlar.length,
      olu: olu.length,
      hata,
    })
  }

  if (toplamJeton === 0) return yanit(200, { gonderildi: 0, neden: 'jeton yok' })
  if (hataVar) return yanit(500, { gonderildi: toplamJeton - toplamOlu, hata: 'kismi basarisizlik' })
  return yanit(200, { gonderildi: toplamJeton - toplamOlu, olu: toplamOlu })
})

// Bildirimler Task 3: "bildirim-gonder" fonksiyonunun SAF mantigi.
// Tam yorumlu kaynak depoda: mobil/supabase/functions/bildirim-gonder/saf.ts

export type Olay =
  | { olay: 'mesaj'; mesaj_id: string; konusma_id: string; gonderen_id: string; aktor_id: string | null }
  | { olay: 'takip_istegi'; takip_eden_id: string; takip_edilen_id: string; aktor_id: string | null }
  | { olay: 'takip_kabul'; takip_eden_id: string; takip_edilen_id: string; aktor_id: string | null }
  // DOGRUDAN EKLEME (2026-09-18): acik profilde "Arkadas ekle" istek
  // gondermez, bagi hemen kurar; eklenen kisiye bu olay gider.
  | { olay: 'takip_eklendi'; takip_eden_id: string; takip_edilen_id: string; aktor_id: string | null }
  | { olay: 'sohbet_istegi'; gonderen_id: string; hedef_id: string; aktor_id: string | null }
  | { olay: 'sohbet_kabul'; gonderen_id: string; hedef_id: string; aktor_id: string | null }
  | {
      olay: 'etiket_istegi'
      check_in_id: string
      etiketlenen_id: string
      etiketleyen_id: string
      aktor_id: string | null
    }
  | {
      olay: 'etiket_eklendi'
      check_in_id: string
      etiketlenen_id: string
      etiketleyen_id: string
      aktor_id: string | null
    }

const UUID_DESENI = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i

function uuidMi(deger: unknown): deger is string {
  return typeof deger === 'string' && UUID_DESENI.test(deger)
}

/** `aktor_id` yoklugu ile null'i ayni sayiyoruz: ikisi de "aktor bilinmiyor". */
function aktoruOku(kayit: Record<string, unknown>): string | null | undefined {
  const ham = kayit.aktor_id
  if (ham === null || ham === undefined) return null
  return uuidMi(ham) ? ham : undefined // undefined = bicim hatasi
}

export function govdeyiCozumle(ham: unknown): Olay | null {
  if (typeof ham !== 'object' || ham === null || Array.isArray(ham)) return null
  const k = ham as Record<string, unknown>

  const aktor = aktoruOku(k)
  if (aktor === undefined) return null

  switch (k.olay) {
    case 'mesaj':
      if (!uuidMi(k.mesaj_id) || !uuidMi(k.konusma_id) || !uuidMi(k.gonderen_id)) return null
      return {
        olay: 'mesaj',
        mesaj_id: k.mesaj_id,
        konusma_id: k.konusma_id,
        gonderen_id: k.gonderen_id,
        aktor_id: aktor,
      }

    case 'takip_istegi':
    case 'takip_kabul':
    case 'takip_eklendi':
      if (!uuidMi(k.takip_eden_id) || !uuidMi(k.takip_edilen_id)) return null
      return {
        olay: k.olay,
        takip_eden_id: k.takip_eden_id,
        takip_edilen_id: k.takip_edilen_id,
        aktor_id: aktor,
      }

    case 'sohbet_istegi':
    case 'sohbet_kabul':
      if (!uuidMi(k.gonderen_id) || !uuidMi(k.hedef_id)) return null
      return {
        olay: k.olay,
        gonderen_id: k.gonderen_id,
        hedef_id: k.hedef_id,
        aktor_id: aktor,
      }

    case 'etiket_istegi':
    case 'etiket_eklendi':
      if (
        !uuidMi(k.check_in_id) ||
        !uuidMi(k.etiketlenen_id) ||
        !uuidMi(k.etiketleyen_id)
      ) {
        return null
      }
      return {
        olay: k.olay,
        check_in_id: k.check_in_id,
        etiketlenen_id: k.etiketlenen_id,
        etiketleyen_id: k.etiketleyen_id,
        aktor_id: aktor,
      }

    default:
      return null
  }
}

export type Hedef = {
  /** Bildirimi ALACAK kisi. */
  aliciId: string
  /** Adi metinde gecen ve istemcinin yonlendirmede kullandigi karsi taraf. */
  karsiTarafId: string
}

/**
 * Olaydan alicilari ve karsi tarafi cikarir.
 *   takip_istegi  -> alici: takip_edilen, karsi taraf: takip_eden
 *   takip_kabul   -> alici: takip_eden (istegi gonderen), karsi taraf: takip_edilen
 *   takip_eklendi -> alici: takip_edilen (eklenen), karsi taraf: takip_eden (ekleyen)
 */
export function hedefleriBelirle(olay: Olay, konusmaDigerUyeleri: string[]): Hedef[] {
  switch (olay.olay) {
    case 'mesaj':
      return konusmaDigerUyeleri.map((uye) => ({ aliciId: uye, karsiTarafId: olay.gonderen_id }))
    case 'takip_istegi':
    case 'takip_eklendi':
      return [{ aliciId: olay.takip_edilen_id, karsiTarafId: olay.takip_eden_id }]
    case 'takip_kabul':
      return [{ aliciId: olay.takip_eden_id, karsiTarafId: olay.takip_edilen_id }]
    case 'sohbet_istegi':
      return [{ aliciId: olay.hedef_id, karsiTarafId: olay.gonderen_id }]
    case 'sohbet_kabul':
      return [{ aliciId: olay.gonderen_id, karsiTarafId: olay.hedef_id }]
    case 'etiket_istegi':
    case 'etiket_eklendi':
      return [{ aliciId: olay.etiketlenen_id, karsiTarafId: olay.etiketleyen_id }]
  }
}

/**
 * Oz-bildirim kurali: kisi kendi eyleminin bildirimini almamali.
 */
export function ozBildirimMi(aliciId: string, aktorId: string | null): boolean {
  return aktorId !== null && aktorId === aliciId
}

/** Profili okunamayan/olmayan kisi icin notr karsilik. */
export const VARSAYILAN_AD = 'Biri'

/**
 * Bildirim govdesini uretir. Mesaj olayinda bile mesajin KENDISI gecmez;
 * kilit ekranina yalnizca "kim" duser.
 */
export function bildirimGovdesi(olay: Olay['olay'], ad: string): string {
  switch (olay) {
    case 'mesaj':
      return `${ad} sana mesaj gönderdi`
    case 'takip_istegi':
      return `${ad} sana arkadaşlık isteği gönderdi`
    case 'takip_kabul':
      return `${ad} arkadaşlık isteğini kabul etti`
    case 'takip_eklendi':
      return `${ad} seni arkadaş olarak ekledi`
    case 'sohbet_istegi':
      return `${ad} sana sohbet isteği gönderdi`
    case 'sohbet_kabul':
      return `${ad} sohbet isteğini kabul etti`
    case 'etiket_istegi':
      return `${ad} seni etiketlemek istiyor`
    case 'etiket_eklendi':
      return `${ad} seni bir check-in'de etiketledi`
  }
}

// Bildirimler Task 3: "bildirim-gonder" Edge Function (Deno).
//
// DEPLOY NOTU: `verify_jwt` KAPALI olmali. Cagriyi pg_net yapiyor ve
// elinde bir kullanici JWT'si yok; yetkilendirme tamamen asagidaki sir
// dogrulamasina dayaniyor. Tam yorumlu kaynak depoda:
// mobil/supabase/functions/bildirim-gonder/index.ts

import { createClient, type SupabaseClient } from 'npm:@supabase/supabase-js@2'
import {
  bildirimGovdesi,
  govdeyiCozumle,
  hedefleriBelirle,
  ozBildirimMi,
  VARSAYILAN_AD,
  type Olay,
} from './saf.ts'

const EXPO_PUSH_URL = 'https://exp.host/--/api/v2/push/send'
const EXPO_PARTI_BOYU = 100

let sirOnbellek: string | null = null
let sonSirOkumasi = 0
const SIR_TAZELEME_ARALIGI_MS = 60_000

async function siriOku(yonetici: SupabaseClient, tazele: boolean): Promise<string | null> {
  if (sirOnbellek !== null && !tazele) return sirOnbellek

  const simdi = Date.now()
  if (sonSirOkumasi !== 0 && simdi - sonSirOkumasi < SIR_TAZELEME_ARALIGI_MS) return sirOnbellek

  const { data, error } = await yonetici.rpc('bildirim_siri_oku')
  sonSirOkumasi = simdi

  if (error) {
    console.error('bildirim-gonder: sir okunamadi', { kod: error.code })
    return sirOnbellek
  }

  if (typeof data === 'string' && data.length > 0) {
    sirOnbellek = data
  } else {
    console.error('bildirim-gonder: sir bos donduruldu')
  }
  return sirOnbellek
}

function esitSir(a: string, b: string): boolean {
  if (a.length !== b.length) return false
  let fark = 0
  for (let i = 0; i < a.length; i++) fark |= a.charCodeAt(i) ^ b.charCodeAt(i)
  return fark === 0
}

/**
 * Olayin gercekten olup olmadigini veritabanina sorar.
 */
async function kaynakDogrula(yonetici: SupabaseClient, olay: Olay): Promise<boolean> {
  try {
    if (olay.olay === 'mesaj') {
      const { data, error } = await yonetici
        .from('mesajlar')
        .select('id')
        .eq('id', olay.mesaj_id)
        .eq('konusma_id', olay.konusma_id)
        .eq('gonderen_id', olay.gonderen_id)
        .limit(1)
      if (error) throw error
      return (data ?? []).length > 0
    }

    if (olay.olay === 'takip_istegi' || olay.olay === 'takip_kabul' || olay.olay === 'takip_eklendi') {
      // takip_eklendi de 'kabul' satiriyla dogrulanir: dogrudan ekleme
      // satiri baslangictan 'kabul' yazar.
      const { data, error } = await yonetici
        .from('takipler')
        .select('durum')
        .eq('takip_eden_id', olay.takip_eden_id)
        .eq('takip_edilen_id', olay.takip_edilen_id)
        .eq('durum', olay.olay === 'takip_istegi' ? 'beklemede' : 'kabul')
        .limit(1)
      if (error) throw error
      return (data ?? []).length > 0
    }

    if (olay.olay === 'etiket_istegi' || olay.olay === 'etiket_eklendi') {
      // IKI SEY birden dogrulaniyor: etiket satiri gercekten var mi ve
      // check-in'in sahibi govdede yazan etiketleyen mi.
      const { data: etiket, error: etiketHatasi } = await yonetici
        .from('check_in_etiketleri')
        .select('durum')
        .eq('check_in_id', olay.check_in_id)
        .eq('kullanici_id', olay.etiketlenen_id)
        .eq('durum', olay.olay === 'etiket_istegi' ? 'bekliyor' : 'onaylandi')
        .limit(1)
      if (etiketHatasi) throw etiketHatasi
      if ((etiket ?? []).length === 0) return false

      const { data: checkIn, error: checkInHatasi } = await yonetici
        .from('check_inler')
        .select('id')
        .eq('id', olay.check_in_id)
        .eq('kullanici_id', olay.etiketleyen_id)
        .limit(1)
      if (checkInHatasi) throw checkInHatasi
      return (checkIn ?? []).length > 0
    }

    // sohbet_istegi / sohbet_kabul. Tablodaki sutun adi `alan_id`,
    // sozlesmedeki alan adi `hedef_id`.
    const { data, error } = await yonetici
      .from('sohbet_istekleri')
      .select('durum')
      .eq('gonderen_id', olay.gonderen_id)
      .eq('alan_id', olay.hedef_id)
      .eq('durum', olay.olay === 'sohbet_istegi' ? 'beklemede' : 'kabul')
      .limit(1)
    if (error) throw error
    return (data ?? []).length > 0
  } catch (e) {
    const kod = (e as { code?: string })?.code
    console.error('bildirim-gonder: kaynak satiri okunamadi', { olay: olay.olay, kod })
    return false
  }
}

async function konusmaDigerUyeleri(
  yonetici: SupabaseClient,
  konusmaId: string,
  gonderenId: string
): Promise<string[]> {
  const { data, error } = await yonetici
    .from('konusma_uyeleri')
    .select('kullanici_id')
    .eq('konusma_id', konusmaId)
    .neq('kullanici_id', gonderenId)

  if (error) {
    console.error('bildirim-gonder: konusma uyeleri okunamadi', { kod: error.code })
    return []
  }
  return (data ?? []).map((s: { kullanici_id: string }) => s.kullanici_id)
}

/** Karsi tarafin gorunen adi; profil yoksa notr karsilik. */
async function adiOku(yonetici: SupabaseClient, kullaniciId: string): Promise<string> {
  const { data, error } = await yonetici
    .from('profiller')
    .select('ad')
    .eq('id', kullaniciId)
    .maybeSingle()

  if (error) {
    console.error('bildirim-gonder: ad okunamadi', { kod: error.code })
    return VARSAYILAN_AD
  }
  const ad = data?.ad as string | undefined
  return ad && ad.trim().length > 0 ? ad : VARSAYILAN_AD
}

async function jetonlariOku(yonetici: SupabaseClient, aliciId: string): Promise<string[]> {
  const { data, error } = await yonetici
    .from('bildirim_jetonlari')
    .select('jeton')
    .eq('kullanici_id', aliciId)

  if (error) {
    console.error('bildirim-gonder: jetonlar okunamadi', { kod: error.code })
    return []
  }
  return (data ?? []).map((s: { jeton: string }) => s.jeton)
}

async function olecekJetonlariSil(
  yonetici: SupabaseClient,
  aliciId: string,
  jetonlar: string[]
): Promise<void> {
  if (jetonlar.length === 0) return
  const { error } = await yonetici
    .from('bildirim_jetonlari')
    .delete()
    .eq('kullanici_id', aliciId)
    .in('jeton', jetonlar)
  if (error) {
    console.error('bildirim-gonder: olu jeton silinemedi', { kod: error.code })
  }
}

type ExpoSonuc = { status?: string; details?: { error?: string } }

function parcala<T>(dizi: T[], boy: number): T[][] {
  const parcalar: T[][] = []
  for (let i = 0; i < dizi.length; i += boy) parcalar.push(dizi.slice(i, i + boy))
  return parcalar
}

async function expoyaGonder(
  jetonlar: string[],
  govde: string,
  data: Record<string, string>
): Promise<{ hata: boolean; olu: string[] }> {
  const olu: string[] = []
  let hata = false

  for (const parca of parcala(jetonlar, EXPO_PARTI_BOYU)) {
    const mesajlar = parca.map((jeton) => ({ to: jeton, body: govde, data, sound: 'default' }))

    let yanit: Response
    try {
      yanit = await fetch(EXPO_PUSH_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
        body: JSON.stringify(mesajlar),
      })
    } catch {
      console.error('bildirim-gonder: Expo cagrisi yapilamadi')
      hata = true
      continue
    }

    if (!yanit.ok) {
      console.error('bildirim-gonder: Expo hata durumu', { durum: yanit.status })
      hata = true
      continue
    }

    let govdeJson: { data?: ExpoSonuc[] }
    try {
      govdeJson = await yanit.json()
    } catch {
      console.error('bildirim-gonder: Expo yaniti cozulemedi')
      hata = true
      continue
    }

    const sonuclar = govdeJson.data ?? []
    if (sonuclar.length !== parca.length) {
      console.error('bildirim-gonder: Expo sonuc sayisi eslesmiyor', {
        beklenen: parca.length,
        gelen: sonuclar.length,
      })
      hata = true
      continue
    }

    sonuclar.forEach((sonuc, i) => {
      if (sonuc?.status === 'error') {
        if (sonuc.details?.error === 'DeviceNotRegistered') olu.push(parca[i])
        else hata = true
      }
    })
  }

  return { hata, olu }
}

function yanit(durum: number, govde: Record<string, unknown>): Response {
  return new Response(JSON.stringify(govde), {
    status: durum,
    headers: { 'Content-Type': 'application/json' },
  })
}

Deno.serve(async (req: Request): Promise<Response> => {
  if (req.method !== 'POST') return yanit(405, { hata: 'yalnizca POST' })

  const supabaseUrl = Deno.env.get('SUPABASE_URL')
  const servisAnahtari = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')
  if (!supabaseUrl || !servisAnahtari) {
    console.error('bildirim-gonder: ortam degiskenleri eksik')
    return yanit(500, { hata: 'yapilandirma eksik' })
  }

  const yonetici = createClient(supabaseUrl, servisAnahtari, {
    auth: { persistSession: false, autoRefreshToken: false },
  })

  // 1) Sir. Dogrulanmadan HICBIR sey yapilmiyor.
  const gelenSir = req.headers.get('X-Bildirim-Sir')
  if (!gelenSir) return yanit(401, { hata: 'yetkisiz' })

  let sir = await siriOku(yonetici, false)
  if (sir === null) {
    return yanit(500, { hata: 'sir okunamadi' })
  }
  if (!esitSir(gelenSir, sir)) {
    sir = await siriOku(yonetici, true)
    if (sir === null || !esitSir(gelenSir, sir)) {
      console.warn('bildirim-gonder: sir eslesmedi')
      return yanit(401, { hata: 'yetkisiz' })
    }
  }

  // 2) Govde BICIMI.
  let ham: unknown
  try {
    ham = await req.json()
  } catch {
    return yanit(400, { hata: 'govde cozulemedi' })
  }

  const olay = govdeyiCozumle(ham)
  if (!olay) return yanit(400, { hata: 'gecersiz olay' })

  // 3) Olay GERCEKTEN oldu mu.
  if (!(await kaynakDogrula(yonetici, olay))) {
    console.warn('bildirim-gonder: olay dogrulanamadi', { olay: olay.olay })
    return yanit(200, { gonderildi: 0, neden: 'olay dogrulanamadi' })
  }

  // 4) Alicilar.
  const digerUyeler =
    olay.olay === 'mesaj'
      ? await konusmaDigerUyeleri(yonetici, olay.konusma_id, olay.gonderen_id)
      : []

  const hedefler = hedefleriBelirle(olay, digerUyeler)
  if (hedefler.length === 0) {
    console.log('bildirim-gonder: alici bulunamadi', { olay: olay.olay })
    return yanit(200, { gonderildi: 0, neden: 'alici yok' })
  }

  const gonderilecekler = hedefler.filter((h) => !ozBildirimMi(h.aliciId, olay.aktor_id))
  if (gonderilecekler.length === 0) {
    console.log('bildirim-gonder: oz-bildirim atlandi', { olay: olay.olay })
    return yanit(200, { gonderildi: 0, neden: 'oz-bildirim' })
  }

  // 5) Metin.
  const ad = await adiOku(yonetici, gonderilecekler[0].karsiTarafId)
  const govde = bildirimGovdesi(olay.olay, ad)

  let toplamJeton = 0
  let toplamOlu = 0
  let hataVar = false

  for (const hedef of gonderilecekler) {
    const jetonlar = await jetonlariOku(yonetici, hedef.aliciId)
    if (jetonlar.length === 0) {
      console.log('bildirim-gonder: jeton yok', { olay: olay.olay, alici: hedef.aliciId })
      continue
    }

    const { hata, olu } = await expoyaGonder(jetonlar, govde, {
      tur: olay.olay,
      kullaniciId: hedef.karsiTarafId,
    })
    await olecekJetonlariSil(yonetici, hedef.aliciId, olu)

    toplamJeton += jetonlar.length
    toplamOlu += olu.length
    hataVar = hataVar || hata

    console.log('bildirim-gonder: alici islendi', {
      olay: olay.olay,
      alici: hedef.aliciId,
      jeton: jetonlar.length,
      olu: olu.length,
      hata,
    })
  }

  if (toplamJeton === 0) return yanit(200, { gonderildi: 0, neden: 'jeton yok' })
  if (hataVar) return yanit(500, { gonderildi: toplamJeton - toplamOlu, hata: 'kismi basarisizlik' })
  return yanit(200, { gonderildi: toplamJeton - toplamOlu, olu: toplamOlu })
})

// Bildirimler Task 3: "bildirim-gonder" fonksiyonunun SAF mantigi.
// Tam yorumlu kaynak depoda: mobil/supabase/functions/bildirim-gonder/saf.ts

export type Olay =
  | { olay: 'mesaj'; mesaj_id: string; konusma_id: string; gonderen_id: string; aktor_id: string | null }
  | { olay: 'takip_istegi'; takip_eden_id: string; takip_edilen_id: string; aktor_id: string | null }
  | { olay: 'takip_kabul'; takip_eden_id: string; takip_edilen_id: string; aktor_id: string | null }
  // DOGRUDAN EKLEME (2026-09-18): acik profilde "Arkadas ekle" istek
  // gondermez, bagi hemen kurar; eklenen kisiye bu olay gider.
  | { olay: 'takip_eklendi'; takip_eden_id: string; takip_edilen_id: string; aktor_id: string | null }
  | { olay: 'sohbet_istegi'; gonderen_id: string; hedef_id: string; aktor_id: string | null }
  | { olay: 'sohbet_kabul'; gonderen_id: string; hedef_id: string; aktor_id: string | null }
  | {
      olay: 'etiket_istegi'
      check_in_id: string
      etiketlenen_id: string
      etiketleyen_id: string
      aktor_id: string | null
    }
  | {
      olay: 'etiket_eklendi'
      check_in_id: string
      etiketlenen_id: string
      etiketleyen_id: string
      aktor_id: string | null
    }

const UUID_DESENI = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i

function uuidMi(deger: unknown): deger is string {
  return typeof deger === 'string' && UUID_DESENI.test(deger)
}

/** `aktor_id` yoklugu ile null'i ayni sayiyoruz: ikisi de "aktor bilinmiyor". */
function aktoruOku(kayit: Record<string, unknown>): string | null | undefined {
  const ham = kayit.aktor_id
  if (ham === null || ham === undefined) return null
  return uuidMi(ham) ? ham : undefined // undefined = bicim hatasi
}

export function govdeyiCozumle(ham: unknown): Olay | null {
  if (typeof ham !== 'object' || ham === null || Array.isArray(ham)) return null
  const k = ham as Record<string, unknown>

  const aktor = aktoruOku(k)
  if (aktor === undefined) return null

  switch (k.olay) {
    case 'mesaj':
      if (!uuidMi(k.mesaj_id) || !uuidMi(k.konusma_id) || !uuidMi(k.gonderen_id)) return null
      return {
        olay: 'mesaj',
        mesaj_id: k.mesaj_id,
        konusma_id: k.konusma_id,
        gonderen_id: k.gonderen_id,
        aktor_id: aktor,
      }

    case 'takip_istegi':
    case 'takip_kabul':
    case 'takip_eklendi':
      if (!uuidMi(k.takip_eden_id) || !uuidMi(k.takip_edilen_id)) return null
      return {
        olay: k.olay,
        takip_eden_id: k.takip_eden_id,
        takip_edilen_id: k.takip_edilen_id,
        aktor_id: aktor,
      }

    case 'sohbet_istegi':
    case 'sohbet_kabul':
      if (!uuidMi(k.gonderen_id) || !uuidMi(k.hedef_id)) return null
      return {
        olay: k.olay,
        gonderen_id: k.gonderen_id,
        hedef_id: k.hedef_id,
        aktor_id: aktor,
      }

    case 'etiket_istegi':
    case 'etiket_eklendi':
      if (
        !uuidMi(k.check_in_id) ||
        !uuidMi(k.etiketlenen_id) ||
        !uuidMi(k.etiketleyen_id)
      ) {
        return null
      }
      return {
        olay: k.olay,
        check_in_id: k.check_in_id,
        etiketlenen_id: k.etiketlenen_id,
        etiketleyen_id: k.etiketleyen_id,
        aktor_id: aktor,
      }

    default:
      return null
  }
}

export type Hedef = {
  /** Bildirimi ALACAK kisi. */
  aliciId: string
  /** Adi metinde gecen ve istemcinin yonlendirmede kullandigi karsi taraf. */
  karsiTarafId: string
}

/**
 * Olaydan alicilari ve karsi tarafi cikarir.
 *   takip_istegi  -> alici: takip_edilen, karsi taraf: takip_eden
 *   takip_kabul   -> alici: takip_eden (istegi gonderen), karsi taraf: takip_edilen
 *   takip_eklendi -> alici: takip_edilen (eklenen), karsi taraf: takip_eden (ekleyen)
 */
export function hedefleriBelirle(olay: Olay, konusmaDigerUyeleri: string[]): Hedef[] {
  switch (olay.olay) {
    case 'mesaj':
      return konusmaDigerUyeleri.map((uye) => ({ aliciId: uye, karsiTarafId: olay.gonderen_id }))
    case 'takip_istegi':
    case 'takip_eklendi':
      return [{ aliciId: olay.takip_edilen_id, karsiTarafId: olay.takip_eden_id }]
    case 'takip_kabul':
      return [{ aliciId: olay.takip_eden_id, karsiTarafId: olay.takip_edilen_id }]
    case 'sohbet_istegi':
      return [{ aliciId: olay.hedef_id, karsiTarafId: olay.gonderen_id }]
    case 'sohbet_kabul':
      return [{ aliciId: olay.gonderen_id, karsiTarafId: olay.hedef_id }]
    case 'etiket_istegi':
    case 'etiket_eklendi':
      return [{ aliciId: olay.etiketlenen_id, karsiTarafId: olay.etiketleyen_id }]
  }
}

/**
 * Oz-bildirim kurali: kisi kendi eyleminin bildirimini almamali.
 */
export function ozBildirimMi(aliciId: string, aktorId: string | null): boolean {
  return aktorId !== null && aktorId === aliciId
}

/** Profili okunamayan/olmayan kisi icin notr karsilik. */
export const VARSAYILAN_AD = 'Biri'

/**
 * Bildirim govdesini uretir. Mesaj olayinda bile mesajin KENDISI gecmez;
 * kilit ekranina yalnizca "kim" duser.
 */
export function bildirimGovdesi(olay: Olay['olay'], ad: string): string {
  switch (olay) {
    case 'mesaj':
      return `${ad} sana mesaj gönderdi`
    case 'takip_istegi':
      return `${ad} sana arkadaşlık isteği gönderdi`
    case 'takip_kabul':
      return `${ad} arkadaşlık isteğini kabul etti`
    case 'takip_eklendi':
      return `${ad} seni arkadaş olarak ekledi`
    case 'sohbet_istegi':
      return `${ad} sana sohbet isteği gönderdi`
    case 'sohbet_kabul':
      return `${ad} sohbet isteğini kabul etti`
    case 'etiket_istegi':
      return `${ad} seni etiketlemek istiyor`
    case 'etiket_eklendi':
      return `${ad} seni bir check-in'de etiketledi`
  }
}

