s=s.replace("""type EtiketProfili = { ad: string; fotograflar: string[] | null }
type EtiketSatiri = {
  check_in_id: string
  kullanici_id: string
  profiller: EtiketProfili | EtiketProfili[] | null
}""","""type EtiketSatiri = {
  check_in_id: string
  kullanici_id: string
}""")
s=s.replace("import { profilFotografiUrl } from './fotograf-url'","import { profilOzetleriniGetir } from './akis'")
open(p,"w",encoding="utf-8",newline="\n").write(s); print("ok")
EOF
