      <View style={stiller.kart}>{children}</View>
    </View>
  )
}

export function Satir({
  ikon,
  etiket,
  aciklama,
  deger,
  sagBilesen,
  sonuncu = false,
  tehlikeli = false,
  okYok = false,
  onPress,
}: {
  ikon?: ReactNode
  etiket: string
  /**
