   * "Profilim gizli" tek basina neyin gizlenecegini soylemiyor -
   * kullanici anahtari cevirmeden once ne olacagini bilmeli.
   */
  aciklama?: string
  deger?: string
  /** Anahtar gibi yerinde duran bir denetim. Verilirse ok cizilmez. */
  sagBilesen?: ReactNode
  sonuncu?: boolean
