   * Baska bir ekrana GITMEYEN eylemler icin (cikis yapmak, yerinde
   * acilan bir onay). Ok bir yere gidildigini soyler; gidilmiyorsa
   * yalan soyler.
   */
  okYok?: boolean
  /** Hesabi silmek gibi geri donusu olmayan eylemler icin. */
  tehlikeli?: boolean
  onPress?: () => void
}) {
