 * Giris adresi yeni adres dogrulanana kadar DEGISMEZ.
 */
export async function yeniAdreseKodGonder(yeniEposta: string): Promise<void> {
  const { error } = await supabase.auth.updateUser({ email: yeniEposta })
  if (error) throw new Error(hataMetni(error))
}

export async function yeniAdresiDogrula(yeniEposta: string, kod: string): Promise<void> {
  const { error } = await supabase.auth.verifyOtp({
    email: yeniEposta,
    token: kod,
    type: 'email_change',
  })
  if (error) throw new Error(hataMetni(error))
}

// ---------------------------------------------------------------------
// Sifre
// ---------------------------------------------------------------------

/** Yeni sifreyi yazar; oturum acik oldugu icin eski sifre sorulmuyor. */
export async function sifreDegistir(yeniSifre: string): Promise<void> {
  const { error } = await supabase.auth.updateUser({ password: yeniSifre })
  if (error) throw new Error(hataMetni(error))
}

// ---------------------------------------------------------------------
// Oturumlar
// ---------------------------------------------------------------------

export type Oturum = {
  id: string
  olusturuldu: string
  sonEtkinlik: string
  /** Ham user-agent; ekran `cihazAdi` ile okunur hale getirir. */
  cihaz: string | null
  ip: string | null
  buCihaz: boolean
}

type SunucuOturum = {
  id: string
  olusturuldu: string
  son_etkinlik: string
  cihaz: string | null
  ip: string | null
  bu_cihaz: boolean
}

export async function oturumlarimiGetir(): Promise<Oturum[]> {
  const { data, error } = await supabase.rpc('oturumlarim')
  if (error) throw new Error(hataMetni(error))
  return ((data ?? []) as SunucuOturum[]).map((s) => ({
    id: s.id,
    olusturuldu: s.olusturuldu,
    sonEtkinlik: s.son_etkinlik,
    cihaz: s.cihaz,
    ip: s.ip,
    buCihaz: s.bu_cihaz,
  }))
}

export async function oturumuKapat(oturumId: string): Promise<void> {
  const { error } = await supabase.rpc('oturumu_kapat', { p_oturum_id: oturumId })
  if (error) throw new Error(hataMetni(error))
}

/** Bu cihaz haric butun oturumlari kapatir. */
export async function digerCihazlardanCik(): Promise<void> {
  const { error } = await supabase.auth.signOut({ scope: 'others' })
  if (error) throw new Error(hataMetni(error))
}

/**
 * User-agent'tan okunur cihaz adi. Expo'nun fetch'i iOS'ta
 * "Slooin/13 CFNetwork/... Darwin/...", Android'de "okhttp/4.x" gibi
 * dizeler gonderiyor; tarayici "Mozilla/5.0 ...". Tam UA gosterilmiyor -
 * kullanici icin anlamsiz.
 */
export function cihazAdi(
  ua: string | null,
  metinler: { iphone: string; android: string; web: string; bilinmeyen: string }
): string {
  if (!ua) return metinler.bilinmeyen
  if (/iPhone|iPad|iOS|CFNetwork|Darwin/i.test(ua)) return metinler.iphone
  if (/Android|okhttp/i.test(ua)) return metinler.android
  if (/Mozilla|Chrome|Safari|Firefox/i.test(ua)) return metinler.web
  return metinler.bilinmeyen
}

