                            bugun: t('sohbet.bugun').toLocaleLowerCase(dil),
                            dun: t('sohbet.dun').toLocaleLowerCase(dil),
                          }),
                        })}
                  </Text>
                </View>
                {o.buCihaz ? (
                  <View style={stiller.rozet} testID="bu-cihaz">
                    <Text style={stiller.rozetYazi}>{t('hesapGuvenlik.buCihaz')}</Text>
                  </View>
