import { useCallback, useState } from 'react'
import { View, Text, Pressable, ScrollView, StyleSheet } from 'react-native'
import { useFocusEffect } from 'expo-router'
import { UstCubuk } from '../../tasarim/UstCubuk'
import { ALT_GEZINME_PAYI } from '../../tasarim/AltGezinme'
import { OnayPenceresi } from '../../tasarim/OnayPenceresi'
import { TelefonIkonu } from '../../tasarim/hesap-ikonlari'
import { yazi, olcek, bosluk, yuvarlak, golge, type Renk } from '../../tasarim/tema'
import { useStiller } from '../../tasarim/tema-baglami'
import {
  cihazAdi,
  digerCihazlardanCik,
  oturumlarimiGetir,
  oturumuKapat,
  type Oturum,
} from '../../../lib/hesap-guvenlik'
import { gorecelZaman } from '../../../lib/zaman'
import { useDil } from '../../../lib/dil'

/**
 * ACIK OTURUMLAR (kullanicinin referans gorseli 2026-09-18, "Giris
 * yaptigin cihazlari yonet"). Sunucudan `oturumlarim` RPC'si: cihaz
 * turu (user-agent'tan), IP, son etkinlik, giris tarihi; bu cihaz
 * basta ve isaretli. Diger her oturumda "Oturumu kapat" (onayli);
 * altta "Diger cihazlardan cikis yap". Bu cihazdan cikis ayarlardaki
 * "Cikis yap" ile - burada degil.
 */
export default function OturumlarEkrani() {
  const stiller = useStiller(stilleriYap)
  const { t } = useDil()
  const [oturumlar, setOturumlar] = useState<Oturum[] | null>(null)
  const [hata, setHata] = useState<string | null>(null)
  const [bilgi, setBilgi] = useState<string | null>(null)
  const [kapatilacak, setKapatilacak] = useState<Oturum | null>(null)
  const [digerleriOnayi, setDigerleriOnayi] = useState(false)

  const yukle = useCallback(() => {
    oturumlarimiGetir()
      .then((o) => {
        setOturumlar(o)
        setHata(null)
      })
      .catch((e) => setHata(e instanceof Error ? e.message : t('ortak.birSorunOldu')))
  }, [t])

  useFocusEffect(
    useCallback(() => {
      yukle()
    }, [yukle])
  )

  async function kapat() {
    if (!kapatilacak) return
    const hedef = kapatilacak
    setKapatilacak(null)
    try {
      await oturumuKapat(hedef.id)
      setOturumlar((m) => (m ? m.filter((o) => o.id !== hedef.id) : m))
      setBilgi(t('hesapGuvenlik.oturumKapatildi'))
      setHata(null)
    } catch (e) {
      setHata(e instanceof Error ? e.message : t('ortak.birSorunOldu'))
    }
  }

  async function digerleriniKapat() {
    setDigerleriOnayi(false)
    try {
      await digerCihazlardanCik()
      setOturumlar((m) => (m ? m.filter((o) => o.buCihaz) : m))
      setBilgi(t('hesapGuvenlik.digerleriKapatildi'))
      setHata(null)
    } catch (e) {
      setHata(e instanceof Error ? e.message : t('ortak.birSorunOldu'))
    }
  }

  const cihazMetinleri = {
    iphone: t('hesapGuvenlik.cihazIphone'),
    android: t('hesapGuvenlik.cihazAndroid'),
    web: t('hesapGuvenlik.cihazWeb'),
    bilinmeyen: t('hesapGuvenlik.cihazBilinmeyen'),
  }
  const digerleriVar = (oturumlar ?? []).some((o) => !o.buCihaz)

  return (
    <View style={stiller.kok}>
      <UstCubuk baslik="" geriEtiketi={t('ortak.geri')} />
      <ScrollView contentContainerStyle={stiller.icerik} showsVerticalScrollIndicator={false}>
        <Text style={stiller.baslik}>{t('hesapGuvenlik.acikOturumlar')}</Text>
        <Text style={stiller.altBaslik}>{t('hesapGuvenlik.oturumlarAlt')}</Text>

        {hata && <Text style={stiller.hata}>{hata}</Text>}
        {bilgi && <Text style={stiller.bilgi}>{bilgi}</Text>}

        {oturumlar?.map((o) => (
          <View key={o.id} style={[stiller.kart, o.buCihaz && stiller.kartBuCihaz]} testID={`oturum-${o.id}`}>
            <View style={stiller.kartUst}>
              <View style={stiller.ikonKutusu}>
                <TelefonIkonu />
              </View>
              <View style={stiller.kartMetin}>
                <View style={stiller.baslikSatiri}>
                  <Text style={stiller.cihaz}>{cihazAdi(o.cihaz, cihazMetinleri)}</Text>
                  {o.buCihaz && (
                    <View style={stiller.rozet}>
                      <Text style={stiller.rozetYazi}>{t('hesapGuvenlik.buCihaz')}</Text>
                    </View>
                  )}
                </View>
                <Text style={stiller.ayrinti}>
                  {t('hesapGuvenlik.sonEtkinlik', { zaman: gorecelZaman(o.sonEtkinlik, t) })}
                </Text>
                <Text style={stiller.ayrinti}>
                  {t('hesapGuvenlik.girisTarihi', { tarih: new Date(o.olusturuldu).toLocaleDateString() })}
                  {o.ip ? ` · ${o.ip}` : ''}
                </Text>
              </View>
            </View>
            {!o.buCihaz && (
              <Pressable
                style={({ pressed }) => [stiller.kapatDugmesi, pressed && stiller.kapatDugmesiBasili]}
                onPress={() => setKapatilacak(o)}
                accessibilityRole="button"
                testID={`oturumu-kapat-${o.id}`}
              >
                <Text style={stiller.kapatYazi}>{t('hesapGuvenlik.oturumuKapat')}</Text>
              </Pressable>
            )}
          </View>
        ))}

        {oturumlar && !digerleriVar && (
          <Text style={stiller.not}>{t('hesapGuvenlik.tekOturum')}</Text>
        )}

        {digerleriVar && (
          <Pressable
            style={({ pressed }) => [stiller.birincil, pressed && stiller.birincilBasili]}
            onPress={() => setDigerleriOnayi(true)}
            accessibilityRole="button"
            testID="digerlerinden-cik"
          >
            <Text style={stiller.birincilYazi}>{t('hesapGuvenlik.digerCihazlardanCik')}</Text>
          </Pressable>
        )}
      </ScrollView>

      <OnayPenceresi
        acikMi={kapatilacak !== null}
        baslik={t('hesapGuvenlik.oturumuKapat')}
        aciklama={kapatilacak ? cihazAdi(kapatilacak.cihaz, cihazMetinleri) : undefined}
        eylemEtiketi={t('hesapGuvenlik.oturumuKapat')}
        onOnay={kapat}
        onVazgec={() => setKapatilacak(null)}
      />
      <OnayPenceresi
        acikMi={digerleriOnayi}
        baslik={t('hesapGuvenlik.digerCihazlardanCik')}
        eylemEtiketi={t('hesapGuvenlik.digerCihazlardanCik')}
        onOnay={digerleriniKapat}
        onVazgec={() => setDigerleriOnayi(false)}
      />
    </View>
  )
}

const stilleriYap = (renk: Renk) => StyleSheet.create({
  kok: { flex: 1, backgroundColor: renk.zemin },
  icerik: { paddingHorizontal: bosluk.sayfa, paddingBottom: ALT_GEZINME_PAYI },
  baslik: {
    fontFamily: yazi.ekranBasligi,
    fontSize: 30,
    lineHeight: 36,
    color: renk.metin,
    letterSpacing: -0.6,
  },
  altBaslik: {
    fontFamily: yazi.govde,
    fontSize: olcek.govde + 1,
    lineHeight: 22,
    color: renk.metinIkincil,
    marginTop: bosluk.s,
    marginBottom: bosluk.l,
  },
  kart: {
    borderWidth: 1,
    borderColor: renk.cizgi,
    borderRadius: yuvarlak.kart + 4,
    backgroundColor: renk.yuzey,
    padding: bosluk.l,
    marginTop: bosluk.m,
  },
  kartBuCihaz: { backgroundColor: renk.turuncuZemin, borderColor: renk.turuncuZemin },
  kartUst: { flexDirection: 'row', gap: bosluk.m, alignItems: 'flex-start' },
  ikonKutusu: {
    width: 44,
    height: 44,
    borderRadius: 12,
    backgroundColor: renk.yuzey,
    borderWidth: 1,
    borderColor: renk.cizgi,
    alignItems: 'center',
    justifyContent: 'center',
  },
  kartMetin: { flex: 1 },
  baslikSatiri: { flexDirection: 'row', alignItems: 'center', gap: bosluk.s, flexWrap: 'wrap' },
  cihaz: { fontFamily: yazi.govdeKalin, fontSize: olcek.govde + 2, color: renk.metin },
  rozet: {
    backgroundColor: renk.turuncu,
    borderRadius: yuvarlak.hap,
    paddingHorizontal: bosluk.s,
    paddingVertical: 2,
  },
  rozetYazi: { fontFamily: yazi.govdeKalin, fontSize: olcek.minik, color: '#FFFFFF' },
  ayrinti: { fontFamily: yazi.govde, fontSize: olcek.kucuk, lineHeight: 19, color: renk.metinIkincil, marginTop: 2 },
  kapatDugmesi: {
    alignSelf: 'flex-start',
    marginTop: bosluk.m,
    borderWidth: 1.5,
    borderColor: renk.yikici,
    borderRadius: yuvarlak.hap,
    paddingHorizontal: bosluk.l,
    paddingVertical: 9,
  },
  kapatDugmesiBasili: { opacity: 0.8 },
  kapatYazi: { fontFamily: yazi.govdeKalin, fontSize: olcek.kucuk, color: renk.yikici },
  not: { fontFamily: yazi.govde, fontSize: olcek.govde, lineHeight: 22, color: renk.metinIkincil, marginTop: bosluk.l },
  bilgi: { fontFamily: yazi.govdeOrta, fontSize: olcek.kucuk, color: renk.turuncuYazi, marginTop: bosluk.s },
  hata: { fontFamily: yazi.govdeOrta, fontSize: olcek.kucuk, color: renk.yikici, marginTop: bosluk.s },
  birincil: {
    backgroundColor: renk.turuncu,
    borderRadius: yuvarlak.hap,
    paddingVertical: 17,
    alignItems: 'center',
    marginTop: bosluk.xl,
    ...golge.yuzer,
  },
  birincilBasili: { opacity: 0.92 },
  birincilYazi: { fontFamily: yazi.govdeKalin, fontSize: olcek.govde + 2, color: '#FFFFFF' },
})

