s = open(p, encoding="utf-8").read()

def rep(a, b):
    global s
    assert a in s, a[:70]
    s = s.replace(a, b)

# Gorunurluk ve Kisiler bolumlerini kaldir; yerine Gizlilik ve etkilesim
i = s.index("        <Bolum baslik={t('ayarlar.bolumGorunurluk')}>")
