  aniHatirlatma: boolean
  /** Gece sessize al: 22.00-08.00 yerel saat. */
  sessizGece: boolean
}

const TERCIH_SUTUNU: Record<keyof BildirimTercihleri, string> = {
  anlik: 'bildirim_anlik',
  mesaj: 'bildirim_mesaj',
  arkadas: 'bildirim_arkadas',
