import { useEffect, useState } from 'react'
import { Text, Switch, StyleSheet } from 'react-native'
import { AyarSayfasi, IkonKutusu } from '../../tasarim/AyarSayfasi'
import { Bolum, Satir } from '../../tasarim/Liste'
import { KisiIkonu, EtiketIkonu } from '../../tasarim/ayar-ikonlari'
import { YorumIkonu } from '../../tasarim/etkilesim-ikonlari'
import { bildirimTercihleriniGetir, bildirimTercihiAyarla, type BildirimTercihleri } from '../../../lib/ayarlar'
import { yazi, olcek, bosluk, type Renk } from '../../tasarim/tema'
import { useRenk, useStiller } from '../../tasarim/tema-baglami'
import { useDil } from '../../../lib/dil'
import { useHataStili } from '../../tasarim/hata-stili'

/**
 * BILDIRIMLER (kullanicinin referans satiri 2026-09-18: "Mesajlar,
 * arkadaslar ve anilar"). Uc anahtar = uc push turu; Edge Function
 * `bildirim-gonder` gondermeden once okur (surum 6). Uygulama ici
 * Bildirimler sekmesi etkilenmez - not olarak yaziyor.
 */
export default function BildirimAyarlariEkrani() {
  const { t } = useDil()
  const renk = useRenk()
  const stiller = useStiller(stilleriYap)
  const hataStili = useHataStili()
  const [tercih, setTercih] = useState<BildirimTercihleri | null>(null)
  const [hata, setHata] = useState<string | null>(null)

  useEffect(() => {
    bildirimTercihleriniGetir()
      .then(setTercih)
      .catch((e) => setHata(e instanceof Error ? e.message : t('ortak.birSorunOldu')))
  }, [t])

  async function degistir(anahtar: keyof BildirimTercihleri, deger: boolean) {
    const onceki = tercih
    setTercih((m) => (m ? { ...m, [anahtar]: deger } : m))
    try {
      await bildirimTercihiAyarla(anahtar, deger)
      setHata(null)
    } catch (e) {
      setTercih(onceki)
      setHata(e instanceof Error ? e.message : t('ortak.birSorunOldu'))
    }
  }

  const anahtar = (k: keyof BildirimTercihleri, etiket: string) => (
    <Switch
      accessibilityLabel={etiket}
      value={tercih?.[k] ?? true}
      onValueChange={(d) => degistir(k, d)}
      disabled={tercih === null}
      trackColor={{ true: renk.turuncu, false: renk.cizgi }}
      thumbColor={renk.yuzey}
      {...({ activeThumbColor: renk.yuzey } as object)}
      testID={`bildirim-${k}`}
    />
  )

  return (
    <AyarSayfasi baslik={t('gizlilikEtkilesim.bildirimler')} altBaslik={t('gizlilikEtkilesim.bildirimAlt')}>
      {hata && <Text style={hataStili}>{hata}</Text>}
      <Bolum>
        <Satir
          ikon={<IkonKutusu><YorumIkonu boyut={20} /></IkonKutusu>}
          etiket={t('gizlilikEtkilesim.mesajlar')}
          aciklama={t('gizlilikEtkilesim.mesajlarAciklama')}
          sagBilesen={anahtar('mesaj', t('gizlilikEtkilesim.mesajlar'))}
        />
        <Satir
          ikon={<IkonKutusu><KisiIkonu /></IkonKutusu>}
          etiket={t('gizlilikEtkilesim.arkadaslarBaslik')}
          aciklama={t('gizlilikEtkilesim.arkadaslarAciklama')}
          sagBilesen={anahtar('arkadas', t('gizlilikEtkilesim.arkadaslarBaslik'))}
        />
        <Satir
          ikon={<IkonKutusu><EtiketIkonu /></IkonKutusu>}
          etiket={t('gizlilikEtkilesim.anilar')}
          aciklama={t('gizlilikEtkilesim.anilarAciklama')}
          sagBilesen={anahtar('ani', t('gizlilikEtkilesim.anilar'))}
          sonuncu
        />
      </Bolum>
      <Text style={stiller.not}>{t('gizlilikEtkilesim.bildirimNot')}</Text>
    </AyarSayfasi>
  )
}

const stilleriYap = (renk: Renk) => StyleSheet.create({
  not: {
    fontFamily: yazi.govde,
    fontSize: olcek.govde,
    lineHeight: 22,
    color: renk.metinIkincil,
    marginTop: bosluk.l,
  },
})

