   * okumuyor - yani disari acilan bir sey yok.
   *
   * Olculdu: bu istisnadan once `slooin.expo.app/gizlilik` oturumsuz
   * acilinca karsilama ekranina yonleniyordu.
   */
  // Kullanim kosullari da ayni sinifta: hesap olusturma adimindaki
  // baglantidan OTURUMSUZ aciliyor (2026-09-13).
  const gizlilikEkraninda = segments[0] === 'gizlilik' || segments[0] === 'kosullar'

  // HESABI OLMAYAN HERKES, HER ACILISTA karsilama ekranini gorur
  // (kullanicinin karari 2026-08-25). Once "yalnizca ilk indirene
  // gosterilsin" denmisti ve isaret cihazda saklaniyordu; o isaret
  // tamamen kaldirildi. Hesap olusturan kisi zaten oturum actigi icin
  // buraya hic dusmuyor.
  if (!oturumVar) return authGrubunda || gizlilikEkraninda ? null : '/karsilama'

export default function KokLayout() {
  // Uygulamanin yazi ailesi. Yuklenmeden once ekran cizilmez:
  // sistem fontuyla bir kare cizip sonra marka fontuna atlamak gozle
  // gorulur bir sicrama uretiyor.
  const [yaziHazir] = useFonts({
    InstrumentSans_400Regular,
    InstrumentSans_500Medium,
    InstrumentSans_600SemiBold,
    InstrumentSans_700Bold,
  })

  if (!yaziHazir) return null

  return (
    // GESTURE KOKU EN DISTA (2026-09-08): akis kartindaki fotograf iki
    // parmakla yakinlastirilabiliyor ve `react-native-gesture-handler`
    // hareketleri ancak bir kok icinde calisiyor. Modal icindeki buyuk
    // gorunum kendi kokunu tasimaya devam ediyor - modal agacin
    // disinda kaldigi icin buradaki kok oraya ulasmiyor.
    <GestureHandlerRootView style={{ flex: 1 }}>
      <SafeAreaProvider>
        <DilSaglayici>
          <OturumSaglayici>
            <DilBekleyerek />
          </OturumSaglayici>
        </DilSaglayici>
      </SafeAreaProvider>
    </GestureHandlerRootView>
  )
}

